def flags(a,b,n=8,sub=False):
 mask=(1<<n)-1; r=(a-b if sub else a+b)&mask; sign=1<<(n-1)
 cf=int(a<b) if sub else int(a+b>mask)
 of=int(bool(((a^b)&(a^r)&sign) if sub else (~(a^b)&(a^r)&sign)))
 return [f'{r:0{n//4}X}H',cf,of,int(bool(r&sign)),int(bool((a^b^r)&16)),int((r&255).bit_count()%2==0),int(r==0)]
flagops=[(0x0F,0x08,False),(0x0F,0xF8,False),(0x4F,0x40,False),(0x81,0xF8,False),(0x0F,0x08,True),(0xF8,0x7F,True)]
