def waveform(bits):
 labels=['Start']+[f'd{i}' for i in range(7)]+['Parity','Stop']
 levels=[1]+bits+[1]; x=30; w=55; points=[f'{x},30']
 for b in bits:
  points += [f'{x},{30 if b else 86}',f'{x+w},{30 if b else 86}']; x+=w
 return '<svg class="wave" viewBox="0 0 620 140" role="img" aria-label="逻辑电平串行帧，按时间从左到右">'+''.join(f'<line x1="{30+j*w}" y1="20" x2="{30+j*w}" y2="95" stroke="#cbd5df" stroke-dasharray="3 4"/><text x="{30+j*w+w/2}" y="115" text-anchor="middle">{labels[j]}</text><text x="{30+j*w+w/2}" y="135" text-anchor="middle">{b}</text>' for j,b in enumerate(bits))+'<polyline fill="none" stroke="#087f8c" stroke-width="3" points="'+' '.join(points)+'"/></svg>'
