ks[8]['body'] += p('MUX 扩展也采用分层选择：8→1 可先让两个 4→1 分别选择低半组/高半组，再由最高选择位决定哪组输出；16→1 可用四个 4→1 做第一层、一个 4→1 做第二层，共五个。若把使能用作组选控制，必须确保输出结构允许连接，不能把普通推挽输出直接相连。')
ks[7]['body'] += p('NAND=NOT(AND)，NOR=NOT(OR)，XNOR=NOT(XOR)。两输入共有四种输入组合，每种组合输出可取 0/1，所以一共 2⁴=16 种二输入布尔函数。多输入 XOR 在输入的 1 个数为奇数时输出 1。')

quizzes=[]
def Q(text,options,correct,why,ref): quizzes.append(dict(text=text,options=options,correct=correct,why=why,ref=ref))
Q('101101B 的十进制数值为', ['43','45','53','55'],1,'32+8+4+1=45。','e01')
Q('3000D 的十六进制表示为', ['BB8H','B8BH','BA8H','C00H'],0,'11×256+11×16+8=3000。','e01')
Q('5655 八进制换成十六进制为', ['B55H','BADH','5655H','DABH'],1,'101 110 101 101 重新按四位分组为 B A D。','e02')
Q('20 位地址、按字节编址的空间为', ['64KiB','1MiB','16MiB','4GiB'],1,'2²⁰ 个地址，每个地址一个字节。','e03')
Q('64 位程序中的 int 大小应由什么确定', ['一定 64 位','只看 RAM 容量','编译目标和数据模型，可用 sizeof 验证','独立变量的地址差'],2,'int 与指针大小可不同。','e04')
