 ('Week 3 Chapter 2',13,[('Q1','e14'),('Q2–3','e15'),('Q4–5','e16'),('Q6','e19'),('Q7–8','e20'),('Q9 延伸阅读','sources')]),
 ('Week 4 Chapter 2',17,[('Q1–7','e12'),('Q8','e13'),('Q9','e17'),('Q10–12','e18')]),
 ('Week 5 实践',20,[('Q1–5、Q9','e21'),('Q6–7','e22'),('Q8','e23')]),
