def coverage_html():
 rows=[]
 for name,i,maps in coverage:
  for q,e in maps: rows.append([name,q,f'<a href="#{e}">{e.upper() if e!="sources" else "材料清单"}</a>',src(i)])
 return '<section class="chapter" id="coverage"><div class="branch">按周回查</div><h2>Tutorial 原题覆盖对照</h2>'+p('相同方法的多道题合并在一个例题组；该组内给出原题数据、结果或实验判读规则。Week 3 Q9 是延伸阅读链接，没有独立计算题。E10、E11、E24、E25、E38、E44 取自讲义/自学内容，用于补足知识与题目的衔接。')+table(['原材料','原题号','讲解位置','原文件'],rows)+'</section>'

def quiz_html():
 out='<section class="chapter" id="quiz"><div class="branch">闭卷自测 · 36 题</div><h2>综合自测：提交后自动判分</h2>'+p('每题 1 分，不限时，可重复作答。题目来源于前面的知识和例题；未作答按 0 分计。讲解册中的大题使用展开答案自查，不纳入这个自动分数。刷新页面会清空作答和草稿。')
 for i,q in enumerate(quizzes):
  out+=f'<div class="quiz-item" id="q{i+1}"><fieldset><legend>{i+1:02} · {html.escape(q["text"])}</legend>'
  for j,o in enumerate(q['options']): out+=f'<label><input type="radio" name="q{i+1}" value="{j}">{chr(65+j)}. {html.escape(o)}</label>'
  out+='</fieldset><div class="feedback" hidden></div></div>'
 out+='<div class="toolbar"><button class="primary" id="grade" type="button">提交自测并查看解析</button><button id="reset" type="button">重做自测</button></div><p class="score" id="score" aria-live="polite"></p><script type="application/json" id="quiz-data">'+json.dumps(quizzes,ensure_ascii=False).replace('</','<\\/')+'</script></section>'
 return out

def page(title,sub,body,toc,workbook=False):
 other=KN if workbook else EX
 subtitle='返回知识主干与分支' if workbook else '进入例题讲解与自测'
 stats=f'<span>{len(ks)} 个知识节点</span><span>{len(es)} 组讲解例题</span><span>{len(quizzes)} 道自动评分题</span><span>Week 1–8 · 离线可用</span>'
 toolbar='<div class="toolbar"><button data-action="print" type="button">打印 / 保存为 PDF</button>'
 if workbook: toolbar+='<button data-action="open" type="button">展开全部答案</button><button data-action="close" type="button">收起全部答案</button><button data-action="challenge" aria-pressed="false" type="button">挑战模式：隐藏方法</button><a href="#quiz">直接开始综合自测 →</a>'
 toolbar+='</div>'
 return '<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="基于当前目录 Week1–8 课件整理的计算机组成离线复习资料"><title>'+title+'</title><style>'+CSS+'</style></head><body id="top"><a class="skip" href="#main">跳至正文</a><aside class="sidebar"><div class="brand">COMPUTER ORGANIZATION</div><h2>计算机组成 · 双册复习</h2><a class="switch" href="'+quote(other)+'">'+subtitle+' ↗</a><label for="search">搜索本册知识、题号或术语</label><input id="search" type="search" placeholder="例如：补码 / DAA / E19" autocomplete="off"><div class="count" id="matchcount" aria-live="polite"></div><nav aria-label="本册目录">'+toc+'</nav><p class="count">先读主干，再沿分支练习。<br>页码均为 PDF 实际页码。</p></aside><main id="main"><header class="hero"><div class="eyebrow">CST301 · REVIEW COMPANION</div><h1>'+title+'</h1><p>'+sub+'</p><div class="stats">'+stats+'</div></header>'+toolbar+'<div class="empty" id="empty">未找到匹配章节。可更换术语或清空搜索。</div>'+body+'<footer class="footer">基于本目录材料重新组织与推导 · 中文讲解保留必要英文术语 · 2026-11-22<br>本册未推断缺失周次及 Chapter 6 内容；自学标识沿用原课件。</footer></main><a class="backtop" href="#top">回到顶部 ↑</a><script>'+SCRIPT+'</script></body></html>'

def build():
 knowledge=''; ktoc=''
 for k in ks:
  refs=''.join(f'<a href="{quote(EX)}#{e}">{e.upper()} · {html.escape(next(x["title"].split('｜',1)[1] for x in es if x["id"]==e))}</a>' for e in k['examples'])
  knowledge+=f'<section class="chapter" id="{k["id"]}"><div class="branch">{k["branch"]}</div><h2>{k["title"]}</h2><div>{k["source"]}</div>'+k['body']+'<div class="refs"><strong>对应讲解册位置</strong><br>'+refs+'</div></section>'
  ktoc+=f'<a href="#{k["id"]}">{k["title"]}</a>'
 knowledge+=source_appendix();ktoc+='<a href="#sources">材料清单与校核说明</a>'
 workbook='<section class="chapter" id="how"><div class="branch">使用方法</div><h2>把方法练成可复现的步骤</h2>'+p('按 E01–E44 的逻辑顺序练习；也可从“原题覆盖对照”按周跳转。先独立写出结果，再看方法与解析。挑战模式会隐藏方法并收起答案，适合第二轮复习。')+p('固定约定：H=十六进制，D=十进制，B=二进制后缀；容量 K/M/G 按课件采用二进制倍率。内存未特别说明时按字节编址，x86 多字节数据采用小端。每题明确区分 8086 与 80386+。')+p('纸笔题与草稿由自己对照解析检查；36 道选择题可自动判分。所有程序是教学示例，汇编语法采用 MASM 风格。浏览器不执行 C/汇编程序。')+'</section>'
 etoc='<a href="#how">使用方法</a><a href="#coverage">按周找原题</a><a href="#quiz">综合自测 · 自动评分</a>'
 for e in es:
  links=''.join(f'<a href="{quote(KN)}#{k}">K{k[1:]} · {html.escape(next(x["title"].split('｜',1)[1] for x in ks if x["id"]==k))}</a>' for k in e['knowledge'])
  workbook+=f'<section class="chapter" id="{e["id"]}"><div class="branch">讲解例题 · {e["id"].upper()}</div><h2>{e["title"]}</h2><div>{e["source"]}</div><div class="refs">'+links+'</div><h3>题目与条件</h3>'+e['prompt']+'<div class="method"><h3>解题依据</h3>'+e['method']+'</div><details class="draft"><summary>写下我的推导（刷新后清空，不自动评分）</summary><textarea aria-label="'+e['id'].upper()+' 解题草稿" placeholder="先写位宽、编码、地址或关键中间结果……"></textarea></details><details class="solution"><summary>展开分步解析与答案</summary><div>'+e['solution']+'</div>'+('<div class="trap"><strong>易错点 / 边界</strong><br>'+e['trap']+'</div>' if e['trap'] else '')+'</details></section>'
  etoc+=f'<a href="#{e["id"]}">{e["title"]}</a>'
 workbook+=coverage_html()+quiz_html()+source_appendix();etoc+='<a href="#sources">材料清单与校核说明</a>'
 (ROOT/KN).write_text(page('知识主干与分支','从数据如何表示，逐步走到 CPU 如何执行程序。每个知识节点都附有对应讲解册的准确跳转位置。',knowledge,ktoc),encoding='utf-8',newline='\n')
 (ROOT/EX).write_text(page('Tutorial 例题讲解与自测','按方法整理原题，以必要讲解连接分步推导。练习、查答案、返回知识点，在同一条复习路径中完成。',workbook,etoc,True),encoding='utf-8',newline='\n')
 print('Built',len(ks),'knowledge nodes,',len(es),'example groups,',len(quizzes),'quizzes')

if __name__=='__main__': build()
